exercise.solution:
use std::sync::mpsc;
use std::sync::{Arc, Mutex};
use std::thread;

// One thread per text. The answers come back in the same order as the texts.
fn word_counts(texts: Vec<String>) -> Vec<usize> {
    let mut handles = Vec::new();
    for text in texts {
        handles.push(thread::spawn(move || text.split_whitespace().count()));
    }
    let mut counts = Vec::new();
    for handle in handles {
        counts.push(handle.join().unwrap());
    }
    counts
}

// One thread per number from 1 to n. Each sends (number, square) through a channel.
fn squares(n: u32) -> Vec<(u32, u32)> {
    let (tx, rx) = mpsc::channel();
    for id in 1..=n {
        let tx = tx.clone();
        thread::spawn(move || {
            tx.send((id, id * id)).unwrap();
        });
    }
    drop(tx);

    let mut results = Vec::new();
    for pair in rx {
        results.push(pair);
    }
    results.sort();
    results
}

// One thread per chunk. Each thread adds its chunk's sum to one shared total.
fn parallel_total(chunks: Vec<Vec<u32>>) -> u32 {
    let total = Arc::new(Mutex::new(0));
    let mut handles = Vec::new();
    for chunk in chunks {
        let total = Arc::clone(&total);
        handles.push(thread::spawn(move || {
            let part: u32 = chunk.iter().sum();
            *total.lock().unwrap() += part;
        }));
    }
    for handle in handles {
        handle.join().unwrap();
    }
    let answer = *total.lock().unwrap();   // copy the number out of the guard
    answer
}

fn main() {
    let texts = vec![
        String::from("one two three"),
        String::new(),
        String::from("  spaced   out  "),
        String::from("the quick brown fox jumps"),
    ];
    println!("{:?}", word_counts(texts));
    println!("{:?}", word_counts(Vec::new()));

    println!("{:?}", squares(4));
    println!("{:?}", squares(0));

    println!("{}", parallel_total(vec![vec![1, 2, 3], vec![10, 20], vec![], vec![100]]));
    println!("{}", parallel_total(Vec::new()));
}
